package main

import (
	"encoding/json"
	"os"
	"strings"
	"testing"
)

func TestHorizonInvestigation(t *testing.T) {
	var fixture struct {
		Cases []struct {
			FEN string `json:"fen"`
		} `json:"cases"`
	}
	b, err := os.ReadFile("/Users/philyawj/projects/Pandafish/tools/benchmark/live/v0.10-twitch-m2-20261112/analysis/stockfish-n500000-confirmed/regression-candidates.json")
	if err != nil {
		t.Fatal(err)
	}
	if err = json.Unmarshal(b, &fixture); err != nil {
		t.Fatal(err)
	}
	commands := []string{"startpos", "fen " + timeoutPosition, "fen " + queenRaidPosition, "fen " + crowdedPosition}
	for _, c := range fixture.Cases {
		commands = append(commands, "fen "+c.FEN)
	}
	type row struct {
		Position  string `json:"position"`
		Nodes     uint64 `json:"nodes"`
		QNodes    uint64 `json:"quiescence_nodes"`
		Caps      uint64 `json:"normal_nonchecked_caps"`
		Tactical  uint64 `json:"normal_caps_with_capture_or_promotion"`
		CheckCaps uint64 `json:"ultimate_cap_in_check"`
	}
	rows := []row{}
	for _, command := range commands {
		g, err := parsePosition(strings.Fields(command))
		if err != nil {
			t.Fatal(err)
		}
		auditQNodes, auditNormalCaps, auditTacticalCaps, auditCheckCaps = 0, 0, 0, 0
		w := searcher{table: newTable(), killers: new(killerTable)}
		if _, _, ok := w.root(g.Position(), rootMoves(g.Position(), nil), 4); !ok {
			t.Fatal("incomplete")
		}
		rows = append(rows, row{command, w.nodes, auditQNodes, auditNormalCaps, auditTacticalCaps, auditCheckCaps})
	}
	fen := "4k3/8/3q4/3p4/2B5/3R3K/8/8 w - - 0 1"
	g, err := parsePosition(strings.Fields("fen " + fen))
	if err != nil {
		t.Fatal(err)
	}
	if inCheck(g.Position()) {
		t.Fatal("fixture must start outside check")
	}
	line, err := parsePosition(strings.Fields("fen " + fen + " moves d3d5 d6d5"))
	if err != nil {
		t.Fatal(err)
	}
	if inCheck(line.Position()) {
		t.Fatal("ordinary cutoff must not be checked")
	}
	if _, err = parsePosition(strings.Fields("fen " + fen + " moves d3d5 d6d5 c4d5")); err != nil {
		t.Fatal(err)
	}
	shallow := quiescence(g.Position(), 2, -searchInfinity, searchInfinity)
	deeper := quiescence(g.Position(), 4, -searchInfinity, searchInfinity)
	if deeper <= shallow+50 {
		t.Fatalf("diagnostic did not distinguish exchange: %d, %d", shallow, deeper)
	}
	result := struct {
		Rows []row  `json:"positions"`
		FEN  string `json:"exchange_fixture"`
		Two  int    `json:"quiescence_2_score_cp"`
		Four int    `json:"quiescence_4_score_cp"`
	}{rows, fen, shallow, deeper}
	b, err = json.MarshalIndent(result, "", "  ")
	if err != nil {
		t.Fatal(err)
	}
	if err = os.WriteFile("/tmp/pandafish-v013-horizon-audit.json", append(b, '\n'), 0644); err != nil {
		t.Fatal(err)
	}
}
